const resp = $input.first().json;

// Surface GraphQL/auth errors clearly
if (resp.errors) {
  throw new Error('Fireflies API error: ' + JSON.stringify(resp.errors.map(e => e.message)));
}

// Handle both wrapped and unwrapped response shapes
const t = resp.data?.transcript ?? resp.transcript;
if (!t) {
  throw new Error('Unexpected Fireflies response shape. Top-level keys: ' + Object.keys(resp).join(', '));
}
if (!t.sentences || !t.sentences.length) {
  throw new Error('Transcript ' + (t.id || '?') + ' has no sentences yet — it may still be processing.');
}

const lines = t.sentences.map(s => `${s.speaker_name || 'Unknown'}: ${s.text}`);
return [{
  json: {
    transcriptId: t.id,
    sessionDate: t.date,
    durationMins: Math.round(t.duration || 0),
    speakerCount: [...new Set(t.sentences.map(s => s.speaker_name))].length,
    transcriptText: lines.join('\n')
  }
}];

// Pull scrubbed text out of the OpenAI node output (handles both output shapes)
const j = $input.first().json;
const scrubbed = j.message?.content || j.choices?.[0]?.message?.content || j.output || j.text;
if (!scrubbed) throw new Error('Could not read scrubbed transcript from OpenAI node output.');
const meta = $('Format Transcript').first().json;
return [{ json: { scrubbedTranscript: scrubbed, sessionDate: meta.sessionDate, durationMins: meta.durationMins, speakerCount: meta.speakerCount } }];

